SELECT DISTINCTROW Normierung.Elektrolyseur, Normierung.Datum, Normierung.Zeit, Normierung.[I Gesamt], [Normierung]![I Gesamt]/GetGewFlaeche() AS i, Normierung.Cc, Normierung.[t An], Normierung.[t Ka], ([Normierung]![t An]+[Normierung]![t Ka])/2 AS tm, Normierung.Uo, qrySummeUElemente.[Mittelwert von Ui] AS Um, [Uo]+(([Um]-[Uo])*3)/([I Gesamt]/2.72)-0.01*(90-[tm])+0.02*(32-[Cc]) AS Unalt, UnBerVgl([Um],[i],[tm],[Cc]) AS UnVgl3, AktiRef() AS iRef, AkttKorrektur() AS tKorr, AktcKorrektur() AS cKorr, UnBer([Um],[i],[tm],[Cc]) AS Un
FROM tblGewDaten, Normierung INNER JOIN qrySummeUElemente ON Normierung.Normierung = qrySummeUElemente.Normierung
WHERE (((Normierung.Datum)>=[tblGewDaten].[Anfangsdatum] And (Normierung.Datum)<=[tblGewDaten].[Enddatum]) AND ((Normierung.[I Gesamt]) Is Not Null) AND ((Normierung.Cc) Is Not Null) AND ((Normierung.[t An]) Is Not Null) AND ((Normierung.[t Ka]) Is Not Null))
ORDER BY Normierung.Elektrolyseur, Normierung.Datum, Normierung.Zeit;
